1	//! GPU-side registration geometry: how pegainfer's paged KV allocations map
2	//! onto pegaflow's per-layer strided arena registration.
3	
4	use cudarc::driver::CudaStream;
5	use pegainfer_kv_cache::KvBuffer;
6	
7	/// bf16 KV cache: every layout stride is counted in elements, bytes are ×2.
8	const ELEM_SIZE: usize = std::mem::size_of::<half::bf16>();
9	
10	/// One strided GPU arena to register as one pegaflow "layer": `num_blocks`
11	/// copy units of `bytes_per_block`, sitting `block_stride_bytes` apart from
12	/// `base_ptr`. A fused buffer (qwen3) contributes one arena per model layer;
13	/// a model with sidecar caches (GLM5.2: MLA latent + index-K per layer, two
14	/// separate allocations sharing pool block ids) contributes several arenas
15	/// per model layer — pegaflow moves whatever arenas are registered under one
16	/// block id together, which is what keeps sidecars in lockstep with their
17	/// main cache.
18	///
19	/// `name` keys the arena for the whole engine lifetime (save/load fan across
20	/// every registered name); it must be unique within the engine.
21	pub struct KvArena {
22	    name: String,
23	    base_ptr: u64,
24	    num_blocks: usize,
25	    bytes_per_block: usize,
26	    block_stride_bytes: usize,
27	}
28	
29	/// Per-layer registration geometry fed to pegaflow's one batched call.
30	///
31	/// Only `data_ptrs` and `size_bytes` differ per layer; the rest are the same
32	/// scalar broadcast across all layers (kept as vectors only to feed pegaflow's
33	/// one batched registration call).
34	pub(crate) struct Registration {
35	    pub(crate) layer_names: Vec<String>,
36	    pub(crate) data_ptrs: Vec<u64>,
37	    pub(crate) size_bytes: Vec<usize>,
38	    pub(crate) num_blocks: Vec<usize>,
39	    pub(crate) bytes_per_block: Vec<usize>,
40	    pub(crate) kv_stride_bytes: Vec<usize>,
41	    pub(crate) segments: Vec<usize>,
42	    pub(crate) block_stride_bytes: Vec<usize>,
43	}
44	
45	impl Registration {
46	    /// Map the fused page-first buffer to pegaflow's per-layer view.
47	    ///
48	    /// Each model layer registers as one pegaflow "layer". Within a page the
49	    /// layout is K then V back-to-back (`layer_stride = 2·kv_block_len`), so a
50	    /// layer's K and V are *contiguous* — one single segment of `layer_stride`
51	    /// bytes copies both, and pegaflow's K/V-split path (which needs the two
52	    /// segments set apart, `kv_stride > bytes_per_block`) does not apply here.
53	    /// What is *not* contiguous is consecutive blocks of one layer: the fused
54	    /// buffer interleaves all layers within a page, so they sit `page_stride`
55	    /// apart. That gap (stride ≠ copy size) is exactly what `block_stride_bytes`
56	    /// decouples.
57	    pub(crate) fn from_buffer(buffer: &KvBuffer, stream: &CudaStream) -> Self {
58	        let layout = buffer.layout();
59	        let num_blocks = buffer.num_blocks();
60	        let base_ptr = buffer.device_ptr(stream);
61	
62	        // One block's copy unit for a layer = its whole [K|V] span in a page.
63	        let layer_bytes = layout.layer_stride * ELEM_SIZE;
64	        let page_stride_bytes = layout.page_stride * ELEM_SIZE;
65	
66	        let arenas: Vec<KvArena> = (0..layout.num_layers)
67	            .map(|layer| KvArena {
68	                name: layer.to_string(),
69	                base_ptr: base_ptr + (layer * layer_bytes) as u64,
70	                num_blocks,
71	                bytes_per_block: layer_bytes,
72	                block_stride_bytes: page_stride_bytes,
73	            })
74	            .collect();
75	        Self::from_arenas(&arenas)
76	    }
77	
78	    /// One pegaflow layer per arena, single-segment (an arena is one copy
79	    /// unit per block by definition; K/V split segments only exist for the
80	    /// symmetric-pair layouts vLLM registers).
81	    pub(crate) fn from_arenas(arenas: &[KvArena]) -> Self {
82	        let n = arenas.len();
83	        let mut reg = Registration {
84	            layer_names: Vec::with_capacity(n),
85	            data_ptrs: Vec::with_capacity(n),
86	            size_bytes: Vec::with_capacity(n),
87	            num_blocks: Vec::with_capacity(n),
88	            bytes_per_block: Vec::with_capacity(n),
89	            kv_stride_bytes: vec![0; n],
90	            segments: vec![1; n],
91	            block_stride_bytes: Vec::with_capacity(n),
92	        };
